package dev.madusha.shangos;

import android.content.Context;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;

/**
 * The cities built into the app (res/raw/cities.txt, about 23,000 towns and cities with 15,000
 * people or more, generated by tools/cities.js from GeoNames). Choosing one needs no location
 * service and no network: the list is searched on the TV.
 *
 * <p>Lines are {@code name|country|admin|latitude|longitude|population}, largest first, so the
 * first matches are the biggest cities.
 */
final class Cities {
    private static volatile Cities loaded;

    private final String[] name, folded, country, admin;
    private final double[] lat, lon;
    private final HashMap<String, String> countryNames = new HashMap<>();

    private Cities(List<String[]> rows) {
        int n = rows.size();
        name = new String[n];
        folded = new String[n];
        country = new String[n];
        admin = new String[n];
        lat = new double[n];
        lon = new double[n];
        for (int i = 0; i < n; i++) {
            String[] r = rows.get(i);
            name[i] = r[0];
            folded[i] = fold(r[0]);
            country[i] = r[1];
            admin[i] = r[2];
            lat[i] = Double.parseDouble(r[3]);
            lon[i] = Double.parseDouble(r[4]);
        }
    }

    /** The built-in list. Reads the file once: call it off the main thread. */
    static Cities of(Context context) throws IOException {
        Cities c = loaded;
        if (c != null) return c;
        int id =
                context.getResources()
                        .getIdentifier("cities", "raw", context.getPackageName());
        if (id == 0) throw new IOException("no city list in this build");
        try (InputStream in = context.getResources().openRawResource(id)) {
            c = parse(in);
        }
        loaded = c;
        return c;
    }

    static Cities parse(InputStream in) throws IOException {
        ArrayList<String[]> rows = new ArrayList<>();
        BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
        for (String line; (line = r.readLine()) != null; ) {
            if (line.isEmpty() || line.startsWith("#")) continue;
            String[] f = line.split("\\|", -1);
            if (f.length >= 5) rows.add(f);
        }
        return new Cities(rows);
    }

    int size() {
        return name.length;
    }

    /** Lower case without accents: "Malmö" and "malmo" match. */
    static String fold(String s) {
        return Normalizer.normalize(s.trim(), Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "")
                .toLowerCase(Locale.ROOT);
    }

    /** "Sri Lanka" for "LK". */
    private String countryName(String code) {
        String n = countryNames.get(code);
        if (n == null) {
            n = new Locale("", code).getDisplayCountry(Locale.ENGLISH);
            countryNames.put(code, n);
        }
        return n;
    }

    /**
     * Up to {@code max} cities for what was typed: names that start with it first (the largest
     * first), then names with a word that starts with it ("york" finds New York). A comma narrows
     * by country: "portland, us" or "colombo, sri lanka".
     */
    List<Places.Place> find(String query, int max) {
        String q = fold(query), wanted = "";
        int comma = q.indexOf(',');
        if (comma >= 0) {
            wanted = q.substring(comma + 1).trim();
            q = q.substring(0, comma).trim();
        }
        ArrayList<Integer> hits = new ArrayList<>();
        if (q.length() == 0) return new ArrayList<>();
        for (int pass = 0; pass < 2 && hits.size() < max; pass++)
            for (int i = 0; i < folded.length && hits.size() < max; i++) {
                boolean match =
                        pass == 0 ? folded[i].startsWith(q) : wordStartsWith(folded[i], q);
                if (match && inCountry(i, wanted) && !hits.contains(i)) hits.add(i);
            }
        ArrayList<Places.Place> out = new ArrayList<>();
        for (int i : hits) {
            boolean twin = false; // another result with the same name in the same country
            for (int j : hits)
                twin |= j != i && name[j].equals(name[i]) && country[j].equals(country[i]);
            out.add(new Places.Place(name[i], detail(i, twin), country[i], lat[i], lon[i]));
        }
        return out;
    }

    private boolean inCountry(int i, String wanted) {
        return wanted.isEmpty()
                || country[i].equalsIgnoreCase(wanted)
                || fold(countryName(country[i])).startsWith(wanted);
    }

    private static boolean wordStartsWith(String text, String q) {
        for (int at = text.indexOf(q); at >= 0; at = text.indexOf(q, at + 1))
            if (at > 0 && !Character.isLetterOrDigit(text.charAt(at - 1))) return true;
        return false;
    }

    /**
     * "United States", or "OR, United States" when two results would look the same: the admin
     * code if it is a name (US states, UK nations), else the coordinates.
     */
    private String detail(int i, boolean twin) {
        String country = countryName(this.country[i]);
        if (!twin) return country;
        String a = admin[i];
        if (!a.isEmpty() && Character.isLetter(a.charAt(0))) return a + ", " + country;
        return String.format(Locale.US, "%s (%.1f, %.1f)", country, lat[i], lon[i]);
    }
}
